"""Tide reduction of single-beam soundings.

Observed depths are reduced to chart datum by subtracting the tide
level interpolated linearly between the surrounding tide nodes:
``reduced = depth - h + datum``.
"""

from __future__ import annotations

import math
from bisect import bisect_left

from .svp import _is_real_number

__all__ = ["reduce"]


def reduce(times, depths, tide_times, levels, datum=0.0):
    """Reduce observed depths with a linear tide interpolation.

    ``times``/``depths`` are equal-length non-empty lists/tuples and
    ``tide_times``/``levels`` are equal-length lists/tuples with at
    least two nodes. Every element and ``datum`` must be a finite
    non-bool int/float; ``depths`` elements must be ``>= 0`` and
    ``tide_times`` strictly increasing. Each observation time must lie
    within the tide time range; a time exactly on a node takes that
    node's level, otherwise the level is linearly interpolated between
    the surrounding nodes ``(t0, h0)`` and ``(t1, h1)``::

        h = h0 + (h1 - h0) * (t - t0) / (t1 - t0)
        reduced = depths[i] - h + datum

    Validation order (first error wins): the four containers, their
    non-emptiness, the equal lengths and the minimum node count, the
    tide elements and their strict increase, then ``datum``, then each
    observation in order (time, depth, time range). Observation errors
    are prefixed with ``"observation[i]: "``.

    Returns a tuple of floats in observation order, each rounded to 6
    decimals (negative zero normalized to ``0.0``). Inputs are not
    modified.
    """
    for name, values in (
        ("times", times),
        ("depths", depths),
        ("tide_times", tide_times),
        ("levels", levels),
    ):
        if not isinstance(values, (list, tuple)):
            raise TypeError(f"{name} must be a list or tuple")

    for name, values in (
        ("times", times),
        ("depths", depths),
        ("tide_times", tide_times),
        ("levels", levels),
    ):
        if len(values) == 0:
            raise ValueError(f"{name} must be non-empty")

    if len(times) != len(depths):
        raise ValueError("times and depths must have equal length")
    if len(tide_times) != len(levels):
        raise ValueError("tide_times and levels must have equal length")
    if len(tide_times) < 2:
        raise ValueError("tide_times must have at least 2 nodes")

    for name, values in (("tide_times", tide_times), ("levels", levels)):
        for item in values:
            if not _is_real_number(item):
                raise TypeError(f"{name} elements must be non-bool int or float")
        for item in values:
            if not math.isfinite(item):
                raise ValueError(f"{name} elements must be finite")
    for k in range(len(tide_times) - 1):
        if not tide_times[k] < tide_times[k + 1]:
            raise ValueError("tide_times must be strictly increasing")

    if not _is_real_number(datum):
        raise TypeError("datum must be a non-bool int or float")
    if not math.isfinite(datum):
        raise ValueError("datum must be finite")

    start = tide_times[0]
    end = tide_times[-1]
    results = []
    for i in range(len(times)):
        t = times[i]
        depth = depths[i]
        prefix = f"observation[{i}]: "
        if not _is_real_number(t):
            raise TypeError(prefix + "times elements must be non-bool int or float")
        if not math.isfinite(t):
            raise ValueError(prefix + "time must be finite")
        if not _is_real_number(depth):
            raise TypeError(prefix + "depths elements must be non-bool int or float")
        if not math.isfinite(depth):
            raise ValueError(prefix + "depth must be finite")
        if not depth >= 0:
            raise ValueError(prefix + "depth must be >= 0")
        if not start <= t <= end:
            raise ValueError(prefix + "time must be within the tide time range")

        k = bisect_left(tide_times, t)
        if k < len(tide_times) and tide_times[k] == t:
            h = levels[k]
        else:
            t0, t1 = tide_times[k - 1], tide_times[k]
            h0, h1 = levels[k - 1], levels[k]
            h = h0 + (h1 - h0) * (t - t0) / (t1 - t0)

        v = round(depth - h + datum, 6)
        results.append(0.0 if v == 0 else float(v))
    return tuple(results)

"""Batch correction of single-beam observations.

Each observation ``(angle, time)`` is ray-traced through the same
layered sound velocity profile via :func:`ocean_sonar.svp.trace`.
"""

from __future__ import annotations

import math

from .svp import _checked_profile, _is_real_number, trace

__all__ = ["correct"]


def correct(z, c, angles, times, z0=0.0):
    """Correct a batch of single-beam observations.

    ``z``/``c`` are equal-length non-empty lists/tuples of non-bool
    int/float: ``z[0] == 0``, strictly increasing, ``c`` all positive.
    ``angles``/``times`` are equal-length non-empty lists/tuples; for
    every ``i`` the pair must be finite non-bool int/float sharing one
    type with ``z0`` (``z0 >= 0``), with ``0 <= angles[i] < 89`` and
    ``times[i] > 0``.

    Validation order (first error wins): the ``angles``/``times``
    containers, their non-emptiness and equal length, then ``z``/``c``,
    then ``z0``, then each observation in order. Observation errors —
    including total internal reflection raised by
    :func:`~ocean_sonar.svp.trace` — are prefixed with
    ``"observation[i]: "``.

    Returns a tuple of ``(x, d)`` pairs in input order, each value a
    float rounded to 6 decimals (negative zero normalized to ``0.0``).
    Inputs are not modified.
    """
    if not isinstance(angles, (list, tuple)):
        raise TypeError("angles must be a list or tuple")
    if not isinstance(times, (list, tuple)):
        raise TypeError("times must be a list or tuple")
    if len(angles) == 0:
        raise ValueError("angles must be non-empty")
    if len(times) == 0:
        raise ValueError("times must be non-empty")
    if len(angles) != len(times):
        raise ValueError("angles and times must have equal length")

    zs = _checked_profile("z", z)
    cs = _checked_profile("c", c)
    if len(zs) != len(cs):
        raise ValueError("z and c must have equal length")
    if zs[0] != 0:
        raise ValueError("z[0] must be 0")
    for k in range(len(zs) - 1):
        if not zs[k] < zs[k + 1]:
            raise ValueError("z must be strictly increasing")
    for speed in cs:
        if not speed > 0:
            raise ValueError("c elements must be positive")

    if not _is_real_number(z0):
        raise TypeError("z0 must be a non-bool int or float")
    if not math.isfinite(z0):
        raise ValueError("z0 must be finite")
    if not z0 >= 0:
        raise ValueError("z0 must be >= 0")

    results = []
    for i in range(len(angles)):
        a = angles[i]
        t = times[i]
        prefix = f"observation[{i}]: "
        if not _is_real_number(a):
            raise TypeError(prefix + "angles elements must be non-bool int or float")
        if not _is_real_number(t):
            raise TypeError(prefix + "times elements must be non-bool int or float")
        if not (type(a) is type(t) is type(z0)):
            raise TypeError(prefix + "angle, time and z0 must have the same type")
        if not math.isfinite(a):
            raise ValueError(prefix + "angle must be finite")
        if not math.isfinite(t):
            raise ValueError(prefix + "time must be finite")
        if not 0 <= a < 89:
            raise ValueError(prefix + "angle must satisfy 0 <= a < 89")
        if not t > 0:
            raise ValueError(prefix + "time must be positive")
        try:
            results.append(trace(z, c, a, t, z0))
        except ValueError as exc:
            raise ValueError(prefix + str(exc)) from exc
    return tuple(results)

"""Sound velocity profile (SVP) ray tracing.

Layered sound-speed model: layer ``i`` covers ``[z[i], z[i+1])`` with
sound speed ``c[i]``; the last layer extends downward without bound and
a boundary depth belongs to the deeper layer.
"""

from __future__ import annotations

import math

__all__ = ["trace"]


def _is_real_number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _checked_profile(name: str, values: object) -> list[float]:
    if not isinstance(values, (list, tuple)):
        raise TypeError(f"{name} must be a list or tuple")
    if len(values) == 0:
        raise ValueError(f"{name} must be non-empty")
    for item in values:
        if not _is_real_number(item):
            raise TypeError(f"{name} elements must be non-bool int or float")
    result = list(values)
    for item in result:
        if not math.isfinite(item):
            raise ValueError(f"{name} elements must be finite")
    return result


def trace(z, c, a, t, z0=0.0):
    """Trace a ray through a layered sound velocity profile.

    ``z``/``c`` are equal-length non-empty lists/tuples of non-bool
    int/float: ``z[0] == 0``, strictly increasing, ``c`` all positive.
    ``a`` (degrees, ``0 <= a < 89``), ``t`` (two-way seconds, ``t > 0``)
    and ``z0`` (``z0 >= 0``) must share one type and all be finite.

    Returns ``(x, d)``: horizontal offset and depth after a one-way
    travel time of ``t / 2``, each rounded to 6 decimals.
    """
    zs = _checked_profile("z", z)
    cs = _checked_profile("c", c)
    if len(zs) != len(cs):
        raise ValueError("z and c must have equal length")
    if zs[0] != 0:
        raise ValueError("z[0] must be 0")
    for k in range(len(zs) - 1):
        if not zs[k] < zs[k + 1]:
            raise ValueError("z must be strictly increasing")
    for speed in cs:
        if not speed > 0:
            raise ValueError("c elements must be positive")

    for name, value in (("a", a), ("t", t), ("z0", z0)):
        if not _is_real_number(value):
            raise TypeError(f"{name} must be a non-bool int or float")
    if not (type(a) is type(t) is type(z0)):
        raise TypeError("a, t and z0 must have the same type")
    for name, value in (("a", a), ("t", t), ("z0", z0)):
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
    if not 0 <= a < 89:
        raise ValueError("a must satisfy 0 <= a < 89")
    if not t > 0:
        raise ValueError("t must be positive")
    if not z0 >= 0:
        raise ValueError("z0 must be >= 0")

    d = float(z0)
    x = 0.0
    r = t / 2
    n = len(zs)

    i = 0
    for k in range(n):
        if zs[k] <= d:
            i = k
        else:
            break
    p = math.sin(math.radians(a)) / cs[i]

    while True:
        speed = cs[i]
        q = p * speed
        if q >= 1:
            raise ValueError("total internal reflection")
        vx = speed * q
        vz = speed * math.sqrt(1 - q * q)
        s = math.inf if i == n - 1 else (zs[i + 1] - d) / vz
        u = r if r <= s else s
        x += vx * u
        d += vz * u
        if r <= s:
            break
        r -= s
        i += 1

    xr = round(x, 6)
    dr = round(d, 6)
    return (0.0 if xr == 0 else xr, 0.0 if dr == 0 else dr)

